<?php require_once __DIR__.'/includes/bootstrap.php'; $stmt=$pdo->query("SELECT p.*, c.name category_name, u.name farmer_name FROM produce p JOIN categories c ON c.id=p.category_id JOIN users u ON u.id=p.farmer_id WHERE p.status='approved' AND p.quantity>0 ORDER BY p.created_at DESC LIMIT 8"); $items=$stmt->fetchAll(); include __DIR__.'/includes/header.php'; ?>
